#[derive(Debug)]
pub struct CemtTemplateParityFixtureExecutor<'a> {
    package_root: PathBuf,
    template_adapter_registry: &'a TransformTemplateAdapterRegistry,
}

impl<'a> CemtTemplateParityFixtureExecutor<'a> {
    pub fn new(
        package_root: impl AsRef<Path>,
        template_adapter_registry: &'a TransformTemplateAdapterRegistry,
    ) -> Self {
        Self {
            package_root: package_root.as_ref().to_path_buf(),
            template_adapter_registry,
        }
    }
}

impl ConversionParityFixtureExecutor for CemtTemplateParityFixtureExecutor<'_> {
    fn execute_conversion_parity_fixture(
        &self,
        descriptor: &ConversionDescriptor,
        fixture: &ConversionParityFixture,
    ) -> ConversionParityFixtureExecution {
        match descriptor.implementation {
            ConversionImplementation::Cemt => execute_cemt_template_parity_fixture(
                descriptor,
                fixture,
                &self.package_root,
                self.template_adapter_registry,
            ),
            ConversionImplementation::Rust => {
                execute_rust_dom_projection_parity_fixture(descriptor, fixture)
            }
        }
    }
}

/// Executable bounded adapter for the packaged DOM-projection CEMT serializers.
///
/// It recognizes the current packaged DOM serializer templates for normal
/// conversion and parity verification; it is not a general-purpose CEMT
/// interpreter.
#[derive(Clone, Debug, Default)]
pub struct DomProjectionParityCemtAdapter;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ConversionDomProjectionParityOutput {
    Html,
    Xml,
}

impl TransformTemplateAdapter for DomProjectionParityCemtAdapter {
    fn id(&self) -> &'static str {
        "dom-projection-parity-cemt"
    }

    fn kind(&self) -> TransformTemplateKind {
        TransformTemplateKind::CemNative
    }

    fn capability(&self) -> TransformTemplateAdapterCapability {
        TransformTemplateAdapterCapability::Executable
    }

    fn matches_template(&self, identity: &FormatIdentity) -> bool {
        identity
            .content_type
            .as_deref()
            .is_some_and(|content_type| {
                content_type_essence(content_type) == CEM_TRANSFORM_CONTENT_TYPE
            })
            || identity
                .schema
                .as_deref()
                .is_some_and(|schema| schema == CEM_TRANSFORM_SCHEMA_URI)
    }

    fn compile(
        &self,
        request: TransformTemplateCompileRequest<'_>,
    ) -> TransformTemplateAdapterResult<TransformTemplateCompileResponse> {
        let template = std::str::from_utf8(&request.template.bytes).map_err(|error| {
            TransformTemplateAdapterError::failed(
                self.id(),
                TransformTemplateAdapterExecutionPhase::Compile,
                error.to_string(),
            )
        })?;
        if !template.contains(r#"template @name="emit-node""#)
            || !template.contains(r#"cem:for-each @select="$input.children""#)
        {
            return Err(TransformTemplateAdapterError::failed(
                self.id(),
                TransformTemplateAdapterExecutionPhase::Compile,
                "template is not a supported DOM projection converter",
            ));
        }
        let output = if template.contains(r#"node.kind == "cdata""#)
            || template.contains(r#"node.kind = "cdata""#)
        {
            "xml"
        } else if template.contains(r#"node.kind == "raw-text""#)
            || template.contains(r#"node.kind = "raw-text""#)
        {
            "html"
        } else {
            return Err(TransformTemplateAdapterError::failed(
                self.id(),
                TransformTemplateAdapterExecutionPhase::Compile,
                "DOM projection converter output kind is not recognized",
            ));
        };

        Ok(TransformTemplateCompileResponse {
            artifact: TransformTemplateCompiledArtifact::new(
                self.id(),
                self.kind(),
                request.template.uri.clone(),
                request.template.identity.clone(),
                request.entrypoint.clone(),
                serde_json::json!({ "domProjectionParityOutput": output }),
            ),
            diagnostics: Vec::new(),
        })
    }

    fn render(
        &self,
        request: TransformTemplateRenderRequest<'_>,
    ) -> TransformTemplateAdapterResult<TransformTemplateRenderResponse> {
        if let TransformArtifactBody::CemTree(primary) = &request.primary_input.body {
            if conversion_dom_projection_parity_target_is_cem_tree(&request) {
                let tree =
                    conversion_dom_projection_formatted_cem_tree(primary, request.target_scope)?;
                return Ok(TransformTemplateRenderResponse {
                    output: TransformTemplateOutputArtifact {
                        uri: None,
                        identity: request.target.cloned(),
                        source_map: tree.source_map().cloned(),
                        body: TransformArtifactBody::Extension(tree),
                        output_spans: Vec::new(),
                    },
                    diagnostics: Vec::new(),
                });
            }

            let output = conversion_dom_projection_parity_output(&request).map_err(|message| {
                TransformTemplateAdapterError::failed(
                    self.id(),
                    TransformTemplateAdapterExecutionPhase::Render,
                    message,
                )
            })?;
            let rendered =
                conversion_render_dom_projection_parity_cem_tree(primary.as_ref(), output)
                    .map_err(|message| {
                        TransformTemplateAdapterError::failed(
                            self.id(),
                            TransformTemplateAdapterExecutionPhase::Render,
                            message,
                        )
                    })?;
            let identity = request.target.cloned().unwrap_or_default();
            let output = TransformTemplateOutputArtifact::encoded_text(None, identity, rendered)
                .map_err(|error| {
                    TransformTemplateAdapterError::failed(
                        self.id(),
                        TransformTemplateAdapterExecutionPhase::Render,
                        error.to_string(),
                    )
                })?;
            return Ok(TransformTemplateRenderResponse {
                output,
                diagnostics: Vec::new(),
            });
        }

        Err(TransformTemplateAdapterError::failed(
            self.id(),
            TransformTemplateAdapterExecutionPhase::Render,
            format!(
                "DOM projection converter requires a typed CEM tree input, got `{}`; explicit JSON compatibility ingress is not permitted",
                request.primary_input.body.representation_id()
            ),
        ))
    }
}

fn conversion_dom_projection_formatted_cem_tree(
    owner: &Arc<CemTreeAstStream>,
    target_scope: &ScopeConfig,
) -> TransformTemplateAdapterResult<Arc<CemtTreeArtifact>> {
    let subject = CemtTreeSubjectRef::new(owner.as_ref());
    let formatter_profile = conversion_dom_projection_parity_formatter_profile(target_scope);
    let producer_function = "converter-cemt";
    let provenance = || CemtOverlayProvenance::Generated {
        function_name: producer_function.to_owned(),
        source_map: None,
    };
    let mut retained_node_paths = Vec::new();
    let mut node_operations = Vec::new();
    conversion_dom_projection_collect_typed_format_operations(
        subject.nodes(),
        None,
        &mut retained_node_paths,
        &mut node_operations,
    )
    .map_err(|message| {
        TransformTemplateAdapterError::failed(
            "dom-projection-parity-cemt",
            TransformTemplateAdapterExecutionPhase::Render,
            message,
        )
    })?;

    Ok(Arc::new(CemtTreeArtifact::formatted(
        Arc::clone(owner),
        None,
        CemtFormattedTreeOverlay {
            envelope: CemtTreeEnvelopeMetadata {
                content_type: CEM_ML_CONTENT_TYPE.to_owned(),
                schema: CEM_ML_SCHEMA_URI.to_owned(),
                category: "cem-tree".to_owned(),
                mode: CemtTreeEnvelopeMode::Document,
                canonical: true,
            },
            producer: CemtOverlayProducer {
                function_name: producer_function.to_owned(),
                formatter_profile: Some(formatter_profile.clone()),
            },
            operations: vec![
                CemtFormatOperation {
                    name: "cem.format-tree".to_owned(),
                    formatter_role: "formatter.boundary".to_owned(),
                    formatter_profile: Some(formatter_profile.clone()),
                    color_role: None,
                    kind: CemtFormatOperationKind::Marker,
                    provenance: provenance(),
                },
                CemtFormatOperation {
                    name: producer_function.to_owned(),
                    formatter_role: "formatter.converter".to_owned(),
                    formatter_profile: Some(formatter_profile),
                    color_role: None,
                    kind: CemtFormatOperationKind::Decision {
                        value: "converter CEMT produced formatted tree".to_owned(),
                    },
                    provenance: provenance(),
                },
            ],
            retained_node_paths,
            node_operations,
        },
    )))
}

fn conversion_dom_projection_collect_typed_format_operations(
    nodes: &[CemTreeAstNode],
    parent: Option<&CemtOwnerPath>,
    retained_node_paths: &mut Vec<CemtOwnerPath>,
    node_operations: &mut Vec<CemtNodeFormatOperation>,
) -> Result<(), String> {
    for (index, node) in nodes.iter().enumerate() {
        let path = match parent {
            Some(parent) => parent.child(index),
            None => CemtOwnerPath::root(index),
        };
        if node
            .name()
            .is_some_and(|name| name.trim_start().starts_with('@'))
        {
            continue;
        }
        if let CemTreeAstNode::Error { code, .. } = node {
            return Err(format!(
                "DOM projection converter cannot format error node `{code}`"
            ));
        }
        if matches!(node, CemTreeAstNode::WriterToken { .. }) {
            return Err("DOM projection converter cannot consume writer-token input".to_owned());
        }

        retained_node_paths.push(path.clone());
        if let CemTreeAstNode::Element { name, children, .. } = node {
            let layout = if name == "strong" {
                CemtFormatLayout::InlineEmphasis
            } else {
                CemtFormatLayout::Inline
            };
            node_operations.push(CemtNodeFormatOperation {
                target: CemtNodeFormatTarget::Owner(path.clone()),
                producer_function: "converter-cemt".to_owned(),
                formatter_role: if layout == CemtFormatLayout::InlineEmphasis {
                    "formatter.inline-emphasis".to_owned()
                } else {
                    "formatter.layout".to_owned()
                },
                color_role: None,
                kind: CemtNodeFormatOperationKind::Layout(layout),
                provenance: CemtOverlayProvenance::Generated {
                    function_name: "converter-cemt".to_owned(),
                    source_map: None,
                },
            });
            conversion_dom_projection_collect_typed_format_operations(
                children,
                Some(&path),
                retained_node_paths,
                node_operations,
            )?;
        } else if let CemTreeAstNode::Document { children, .. } = node {
            conversion_dom_projection_collect_typed_format_operations(
                children,
                Some(&path),
                retained_node_paths,
                node_operations,
            )?;
        }
    }
    Ok(())
}

fn conversion_dom_projection_parity_target_is_cem_tree(
    request: &TransformTemplateRenderRequest<'_>,
) -> bool {
    request.target.is_some_and(|target| {
        target
            .content_type
            .as_deref()
            .is_some_and(|content_type| content_type_essence(content_type) == CEM_ML_CONTENT_TYPE)
            || target
                .schema
                .as_deref()
                .is_some_and(|schema| schema == CEM_ML_SCHEMA_URI)
    })
}

fn conversion_dom_projection_parity_output(
    request: &TransformTemplateRenderRequest<'_>,
) -> Result<ConversionDomProjectionParityOutput, String> {
    if let Some(content_type) = request
        .target
        .and_then(|target| target.content_type.as_deref())
    {
        let essence = content_type_essence(content_type);
        if essence == HTML_CONTENT_TYPE {
            return Ok(ConversionDomProjectionParityOutput::Html);
        }
        if essence == XML_CONTENT_TYPE {
            return Ok(ConversionDomProjectionParityOutput::Xml);
        }
    }

    match request
        .compiled
        .opaque
        .get("domProjectionParityOutput")
        .and_then(Value::as_str)
    {
        Some("html") => Ok(ConversionDomProjectionParityOutput::Html),
        Some("xml") => Ok(ConversionDomProjectionParityOutput::Xml),
        _ => Err("DOM projection converter target output kind is not recognized".to_owned()),
    }
}

fn conversion_render_dom_projection_parity_cem_tree(
    input: &CemTreeAstStream,
    output: ConversionDomProjectionParityOutput,
) -> Result<String, String> {
    let mut rendered = String::new();
    for node in input.as_nodes() {
        conversion_render_dom_projection_parity_cem_tree_node(node, output, &mut rendered)?;
    }
    Ok(rendered)
}

fn conversion_render_dom_projection_parity_cem_tree_node(
    node: &CemTreeAstNode,
    output: ConversionDomProjectionParityOutput,
    rendered: &mut String,
) -> Result<(), String> {
    match node {
        CemTreeAstNode::Document { children, .. } => {
            for child in children {
                conversion_render_dom_projection_parity_cem_tree_node(child, output, rendered)?;
            }
            Ok(())
        }
        CemTreeAstNode::Element {
            name,
            attributes,
            children,
            ..
        } => {
            if name.starts_with('@') {
                return Ok(());
            }
            rendered.push('<');
            rendered.push_str(name);
            for attribute in attributes {
                conversion_render_dom_projection_parity_cem_tree_attribute(
                    attribute, output, rendered,
                );
            }
            rendered.push('>');
            for child in children {
                conversion_render_dom_projection_parity_cem_tree_node(child, output, rendered)?;
            }
            rendered.push_str("</");
            rendered.push_str(name);
            rendered.push('>');
            Ok(())
        }
        CemTreeAstNode::Text { value, .. } => {
            conversion_escape_text_into(rendered, value);
            Ok(())
        }
        CemTreeAstNode::Whitespace { data, .. } => {
            rendered.push_str(data);
            Ok(())
        }
        CemTreeAstNode::Comment { data, .. } => {
            rendered.push_str("<!--");
            rendered.push_str(data);
            rendered.push_str("-->");
            Ok(())
        }
        CemTreeAstNode::Cdata { data, .. }
            if output == ConversionDomProjectionParityOutput::Xml =>
        {
            rendered.push_str("<![CDATA[");
            rendered.push_str(data);
            rendered.push_str("]]>");
            Ok(())
        }
        CemTreeAstNode::ProcessingInstruction { target, data, .. }
            if output == ConversionDomProjectionParityOutput::Xml =>
        {
            rendered.push_str("<?");
            rendered.push_str(target);
            if !data.is_empty() {
                rendered.push(' ');
                rendered.push_str(data);
            }
            rendered.push_str("?>");
            Ok(())
        }
        CemTreeAstNode::RawText { data, .. }
            if output == ConversionDomProjectionParityOutput::Html =>
        {
            rendered.push_str(data);
            Ok(())
        }
        _ => Ok(()),
    }
}

fn conversion_render_dom_projection_parity_cem_tree_attribute(
    attribute: &CemTreeAstAttribute,
    output: ConversionDomProjectionParityOutput,
    rendered: &mut String,
) {
    rendered.push(' ');
    rendered.push_str(&attribute.name);
    if output == ConversionDomProjectionParityOutput::Html && attribute.value.is_none() {
        return;
    }
    rendered.push_str("=\"");
    if let Some(value) = attribute.value.as_deref() {
        match output {
            ConversionDomProjectionParityOutput::Html => {
                conversion_escape_html_attribute_into(rendered, value);
            }
            ConversionDomProjectionParityOutput::Xml => {
                conversion_escape_xml_attribute_into(rendered, value);
            }
        }
    }
    rendered.push('"');
}

fn conversion_dom_projection_parity_formatter_profile(target_scope: &ScopeConfig) -> String {
    target_scope
        .cemt_formatter_profile
        .as_deref()
        .or(target_scope.cemt_formatter.as_deref())
        .map(str::trim)
        .filter(|profile| !profile.is_empty())
        .map(|profile| match profile {
            "compact" | "pretty" | "tabular" => profile,
            "format-tree" | "cem.format-tree" | "canonical" => "compact",
            _ => profile,
        })
        .unwrap_or("compact")
        .to_owned()
}

