    #[test]
    fn declared_converter_parity_fixtures_load_file_inputs() {
        let package = load_builtin_schema_package(CEM_DOM_PROJECTION_SCHEMA_URI).unwrap();
        let descriptors = conversion_descriptors_from_schema_package(&package).unwrap();
        let html = descriptors
            .iter()
            .find(|descriptor| descriptor.id == "cem-dom-projection-to-html-cemt")
            .expect("HTML converter descriptor");

        let fixtures = load_conversion_parity_fixtures(html, env!("CARGO_MANIFEST_DIR"))
            .expect("declared parity fixture loads from package path");

        assert_eq!(fixtures.len(), 1);
        let fixture = &fixtures[0];
        assert_eq!(fixture.id, "basic-dom");
        assert!(fixture.expected_diagnostics.is_empty());
        assert!(fixture.expected_diagnostic_codes.is_empty());
        let input = fixture.input.as_object().expect("fixture input object");
        assert_eq!(
            input.get("path").and_then(Value::as_str),
            Some("schema-packages/cem-dom-projection/v1/examples/basic-dom.cem-bin")
        );
        assert_eq!(
            input.get("contentType").and_then(Value::as_str),
            Some(CEM_DOM_PROJECTION_CONTENT_TYPE)
        );
        assert_eq!(
            input.get("schema").and_then(Value::as_str),
            Some(CEM_DOM_PROJECTION_SCHEMA_URI)
        );
        let bytes = input
            .get("bytes")
            .and_then(Value::as_array)
            .expect("byte array");
        let expected_bytes = std::fs::read(
            std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("schema-packages/cem-dom-projection/v1/examples/basic-dom.cem-bin"),
        )
        .expect("read expected fixture");
        assert_eq!(bytes.len(), expected_bytes.len());
        assert!(!bytes.is_empty());
    }

    #[test]
    fn rust_dom_projection_parity_executor_renders_declared_fixture_outputs() {
        let registry = ConversionRegistry::with_builtin_converters();
        let html = registry
            .converter("cem-dom-projection-to-html-rust")
            .expect("HTML Rust converter");
        let xml = registry
            .converter("cem-dom-projection-to-xml-rust")
            .expect("XML Rust converter");
        let cemt_html = registry
            .converter("cem-dom-projection-to-html-cemt")
            .expect("HTML CEMT converter");
        let fixtures = load_conversion_parity_fixtures(cemt_html, env!("CARGO_MANIFEST_DIR"))
            .expect("declared parity fixture loads from package path");
        let fixture = fixtures.first().expect("declared fixture");
        let executor = RustDomProjectionParityFixtureExecutor;
        let expected =
            "<article id=\"welcome\"><h1>Welcome</h1><p>This is a minimal CEM-ML document.</p></article>";

        let html_execution = executor.execute_conversion_parity_fixture(html, fixture);
        assert!(
            html_execution.diagnostics.is_empty(),
            "{:?}",
            html_execution.diagnostics
        );
        assert_eq!(
            html_execution.output,
            Some(Value::String(expected.to_owned()))
        );

        let xml_execution = executor.execute_conversion_parity_fixture(xml, fixture);
        assert!(
            xml_execution.diagnostics.is_empty(),
            "{:?}",
            xml_execution.diagnostics
        );
        assert_eq!(
            xml_execution.output,
            Some(Value::String(expected.to_owned()))
        );
    }

    #[test]
    fn cemt_template_parity_executor_checks_declared_contract_fixture() {
        let registry = ConversionRegistry::with_builtin_converters();
        let (contracts, diagnostics) = registry.cemt_native_parity_contracts();
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        let html_contract = contracts
            .iter()
            .find(|contract| contract.cemt.id == "cem-dom-projection-to-html-cemt")
            .expect("HTML CEMT parity contract");
        let fixtures =
            load_conversion_parity_fixtures(html_contract.cemt, env!("CARGO_MANIFEST_DIR"))
                .expect("declared parity fixture loads from package path");
        let mut template_adapters = TransformTemplateAdapterRegistry::new();
        template_adapters.register(DomProjectionParityCemtAdapter);
        let executor =
            CemtTemplateParityFixtureExecutor::new(env!("CARGO_MANIFEST_DIR"), &template_adapters);

        let cemt_execution = executor.execute_conversion_parity_fixture(
            html_contract.cemt,
            fixtures.first().expect("declared fixture"),
        );
        assert!(
            cemt_execution.diagnostics.is_empty(),
            "{:?}",
            cemt_execution.diagnostics
        );

        let diagnostics = evaluate_conversion_parity_fixtures(html_contract, &fixtures, &executor);

        assert!(diagnostics.is_empty(), "{diagnostics:?}");
    }

    #[test]
    fn dom_projection_cemt_adapter_builds_formatted_cem_tree_envelope() {
        let owner = Arc::new(CemTreeAstStream::new(vec![CemTreeAstNode::Element {
            name: "article".to_owned(),
            attributes: Vec::new(),
            children: vec![
                CemTreeAstNode::Text {
                    value: "Ready ".to_owned(),
                    source: SourceMapStack::default(),
                },
                CemTreeAstNode::Element {
                    name: "strong".to_owned(),
                    attributes: Vec::new(),
                    children: vec![CemTreeAstNode::Text {
                        value: "now".to_owned(),
                        source: SourceMapStack::default(),
                    }],
                    source: SourceMapStack::default(),
                },
            ],
            source: SourceMapStack::default(),
        }]));
        let tree = conversion_dom_projection_formatted_cem_tree(
            &owner,
            &ScopeConfig {
                cemt_formatter_profile: Some("acme.showcase.format-tree".to_owned()),
                ..ScopeConfig::default()
            },
        )
        .expect("DOM CEMT adapter tree");

        assert!(Arc::ptr_eq(tree.owner(), &owner));
        assert_eq!(tree.stage(), CemtTreeArtifactStage::Formatted);
        let overlay = tree.formatted_overlay().expect("typed formatter overlay");
        assert_eq!(overlay.envelope.content_type, CEM_ML_CONTENT_TYPE);
        assert_eq!(overlay.envelope.schema, CEM_ML_SCHEMA_URI);
        assert_eq!(overlay.envelope.category, "cem-tree");
        assert_eq!(overlay.envelope.mode, CemtTreeEnvelopeMode::Document);
        assert!(overlay.envelope.canonical);
        assert_eq!(
            overlay.producer.formatter_profile.as_deref(),
            Some("acme.showcase.format-tree")
        );
        assert_eq!(overlay.operations[0].name, "cem.format-tree");
        assert_eq!(overlay.operations[1].name, "converter-cemt");
        assert_eq!(owner.as_nodes()[0].source_map(), &SourceMapStack::default());
        assert!(owner.as_nodes()[0].attributes().is_empty());
        assert!(overlay.node_operations.iter().any(|operation| {
            operation.target == CemtNodeFormatTarget::Owner(CemtOwnerPath::root(0))
                && operation.kind == CemtNodeFormatOperationKind::Layout(CemtFormatLayout::Inline)
        }));
        assert!(overlay.node_operations.iter().any(|operation| {
            operation.target == CemtNodeFormatTarget::Owner(CemtOwnerPath::root(0).child(1))
                && operation.kind
                    == CemtNodeFormatOperationKind::Layout(CemtFormatLayout::InlineEmphasis)
        }));
    }

    #[test]
    fn dom_projection_native_adapter_retains_owner_maps_and_typed_layout() {
        let source_map = SourceMapStack {
            frames: vec![crate::source_map::SourceMapFrame {
                source_id: SourceId(73),
                span: crate::source_map::FrameSpan::Single(crate::source::ByteRange::new(4, 18)),
                transform: crate::source_map::TransformKind::CemAstBuilder,
            }],
        };
        let owner = Arc::new(CemTreeAstStream::new(vec![CemTreeAstNode::Element {
            name: "article".to_owned(),
            attributes: vec![CemTreeAstAttribute {
                name: "id".to_owned(),
                value: Some("ready".to_owned()),
                source: source_map.clone(),
            }],
            children: vec![CemTreeAstNode::Element {
                name: "strong".to_owned(),
                attributes: Vec::new(),
                children: vec![CemTreeAstNode::Text {
                    value: "Ready".to_owned(),
                    source: source_map.clone(),
                }],
                source: source_map.clone(),
            }],
            source: source_map.clone(),
        }]));

        let artifact = conversion_dom_projection_formatted_cem_tree(
            &owner,
            &ScopeConfig {
                cemt_formatter_profile: Some("pretty".to_owned()),
                ..ScopeConfig::default()
            },
        )
        .expect("native DOM projection result");

        assert!(Arc::ptr_eq(artifact.owner(), &owner));
        assert_eq!(artifact.stage(), CemtTreeArtifactStage::Formatted);
        assert_eq!(artifact.subject().nodes()[0].source_map(), &source_map);
        assert_eq!(
            artifact.subject().nodes()[0].attributes()[0].source,
            source_map
        );
        assert_eq!(
            artifact
                .evaluator_view()
                .resolve_path("nodes.0.kind")
                .and_then(|value| value.as_str()),
            Some("element")
        );
        let overlay = artifact.formatted_overlay().expect("typed format overlay");
        assert_eq!(
            overlay.producer.formatter_profile.as_deref(),
            Some("pretty")
        );
        assert!(overlay.retains_node(&CemtOwnerPath::root(0)));
        assert!(overlay.retains_node(&CemtOwnerPath::root(0).child(0)));
        assert!(overlay.node_operations.iter().any(|operation| {
            operation.target == CemtNodeFormatTarget::Owner(CemtOwnerPath::root(0).child(0))
                && operation.kind
                    == CemtNodeFormatOperationKind::Layout(CemtFormatLayout::InlineEmphasis)
        }));
    }

    #[test]
    fn dom_projection_native_adapter_preserves_supported_node_semantics() {
        let source_map = SourceMapStack {
            frames: vec![crate::source_map::SourceMapFrame {
                source_id: SourceId(74),
                span: crate::source_map::FrameSpan::Single(crate::source::ByteRange::new(8, 12)),
                transform: crate::source_map::TransformKind::CemAstBuilder,
            }],
        };
        let owner = Arc::new(CemTreeAstStream::new(vec![
            CemTreeAstNode::Element {
                name: "@doc".to_owned(),
                attributes: Vec::new(),
                children: Vec::new(),
                source: source_map.clone(),
            },
            CemTreeAstNode::Whitespace {
                data: " ".to_owned(),
                source: source_map.clone(),
            },
            CemTreeAstNode::Comment {
                data: "note".to_owned(),
                source: source_map.clone(),
            },
            CemTreeAstNode::ProcessingInstruction {
                name: "build".to_owned(),
                target: "build".to_owned(),
                data: "ready".to_owned(),
                source: source_map.clone(),
            },
            CemTreeAstNode::Cdata {
                data: "<raw>".to_owned(),
                source: source_map.clone(),
            },
            CemTreeAstNode::RawText {
                data: "const ready = true;".to_owned(),
                source: source_map.clone(),
            },
            CemTreeAstNode::Element {
                name: "svg:circle".to_owned(),
                attributes: vec![CemTreeAstAttribute {
                    name: "xml:lang".to_owned(),
                    value: Some("en".to_owned()),
                    source: source_map.clone(),
                }],
                children: vec![CemTreeAstNode::Text {
                    value: "ready".to_owned(),
                    source: source_map.clone(),
                }],
                source: source_map.clone(),
            },
        ]));

        let artifact = conversion_dom_projection_formatted_cem_tree(
            &owner,
            &ScopeConfig {
                cemt_formatter_profile: Some("tabular".to_owned()),
                ..ScopeConfig::default()
            },
        )
        .expect("supported DOM nodes remain typed");
        let overlay = artifact.formatted_overlay().expect("typed format overlay");

        assert!(Arc::ptr_eq(artifact.owner(), &owner));
        assert!(!overlay.retains_node(&CemtOwnerPath::root(0)));
        for index in 1..owner.as_nodes().len() {
            assert!(overlay.retains_node(&CemtOwnerPath::root(index)));
            assert_eq!(artifact.subject().nodes()[index].source_map(), &source_map);
        }
        assert_eq!(
            overlay.producer.formatter_profile.as_deref(),
            Some("tabular")
        );
        assert_eq!(
            conversion_render_dom_projection_parity_cem_tree(
                owner.as_ref(),
                ConversionDomProjectionParityOutput::Html,
            )
            .expect("HTML oracle"),
            " <!--note-->const ready = true;<svg:circle xml:lang=\"en\">ready</svg:circle>"
        );
        assert_eq!(
            conversion_render_dom_projection_parity_cem_tree(
                owner.as_ref(),
                ConversionDomProjectionParityOutput::Xml,
            )
            .expect("XML oracle"),
            " <!--note--><?build ready?><![CDATA[<raw>]]><svg:circle xml:lang=\"en\">ready</svg:circle>"
        );

        let error_owner = Arc::new(CemTreeAstStream::new(vec![CemTreeAstNode::Error {
            code: "cem.dom.invalid".to_owned(),
            source: source_map,
        }]));
        let error =
            conversion_dom_projection_formatted_cem_tree(&error_owner, &ScopeConfig::default())
                .expect_err("DOM error nodes remain explicit adapter failures");
        assert!(error.to_string().contains("cem.dom.invalid"));
    }

    #[test]
    fn dom_projection_native_adapter_has_no_serialized_stage_boundary() {
        let source = include_str!("conversion.rs");
        let native_branch = source
            .split_once("if let TransformArtifactBody::CemTree(primary)")
            .expect("DOM native adapter branch")
            .1
            .split_once("fn conversion_dom_projection_formatted_cem_tree(")
            .expect("DOM adapter implementation boundary")
            .0;
        for required in [
            "conversion_dom_projection_formatted_cem_tree",
            "TransformArtifactBody::Extension(tree)",
        ] {
            assert!(native_branch.contains(required), "missing `{required}`");
        }
        for forbidden in [
            "into_cemt_subject",
            "serde_json",
            "CemtOutputArtifact",
            "cemt_output_body",
            "conversion_dom_projection_parity_cem_tree_document",
        ] {
            assert!(
                !native_branch.contains(forbidden),
                "native DOM adapter must not use `{forbidden}`"
            );
        }

        let typed_builder = source
            .split_once("fn conversion_dom_projection_formatted_cem_tree(")
            .expect("typed DOM result builder")
            .1
            .split_once("fn conversion_dom_projection_parity_target_is_cem_tree")
            .expect("typed DOM result builder boundary")
            .0;
        for forbidden in [
            "Value",
            "serde_json",
            "into_cemt_subject",
            "to_cemt_subject",
        ] {
            assert!(
                !typed_builder.contains(forbidden),
                "typed DOM result builder must not use `{forbidden}`"
            );
        }

        let real_source = include_str!("real.rs");
        let production_handoff = real_source
            .split_once("fn render_export_conversion_template(")
            .expect("production DOM render handoff")
            .1
            .split_once("fn select_converter_template_adapter(")
            .expect("production DOM render handoff boundary")
            .0;
        assert!(production_handoff.contains(
            "execute_conversion_output_pipeline_from_typed_formatted_cem_tree_with_context"
        ));
        assert!(!production_handoff.contains("transform_template_output_cemt_subject"));
        assert!(!production_handoff
            .contains("execute_conversion_output_pipeline_from_formatted_cem_tree_with_context"));
    }

