    #[test]
    fn builtin_csv_lifecycle_output_uses_typed_materialized_ast_pipeline() {
        use crate::validation::csv::{
            csv_document_ast_from_source_bytes, CsvSourceValidationRequest,
        };

        let schema_registry = SchemaRegistry::with_builtin_schemas();
        let conversion_registry = ConversionRegistry::with_builtin_converters();
        let environment = ConversionOutputPipelineEnvironment {
            schema_registry: &schema_registry,
            conversion_registry: &conversion_registry,
            package_artifact_reader: None,
            artifact_cache: None,
        };
        let source = b"id,name,score\n1,\"Ada, A.\",1.2300e+4\n2,Lin,\n";
        let (document, diagnostics) =
            csv_document_ast_from_source_bytes(CsvSourceValidationRequest {
                bytes: source,
                source_uri: "builtin:typed-csv-output",
                content_type: Some("text/csv; header=present"),
            });
        assert!(
            diagnostics
                .iter()
                .all(|diagnostic| !diagnostic.severity.is_hard_violation()),
            "{diagnostics:?}"
        );
        let document = document.expect("typed CSV AST");
        for profile in ["compact", "pretty", "tabular"] {
            let target_scope = ScopeConfig {
                cemt_formatter_profile: Some(profile.to_owned()),
                ..ScopeConfig::default()
            };
            let execution = execute_csv_document_output_pipeline_with_environment(
                &environment,
                document.clone(),
                &target_scope,
                Some("builtin:typed-csv-output"),
            );
            assert!(
                execution.diagnostics.is_empty(),
                "{profile}: {:?}",
                execution.diagnostics
            );
            if profile == "compact" {
                assert_eq!(
                    execution.output.as_ref().and_then(Value::as_str),
                    Some("id,name,score\n1,\"Ada, A.\",1.2300e+4\n2,Lin,\n")
                );
            }
            let materialized = execution
                .formatted_materialized_cemt_tree
                .as_ref()
                .unwrap_or_else(|| panic!("{profile} materialized CSV tree"));
            assert_eq!(
                materialized.input_provenance().representation_id,
                "cem.csv-document-ast"
            );
            assert!(materialized
                .owner()
                .as_nodes()
                .iter()
                .all(|node| matches!(node, CemTreeAstNode::WriterToken { .. })));
            let stage_output = execution
                .materialized_cemt_stage_output
                .as_ref()
                .unwrap_or_else(|| panic!("{profile} typed CSV stage output"));
            let TransformArtifactBody::MaterializedCemtTree(selected) = &stage_output.body else {
                panic!("{profile} CSV stage output must be materialized")
            };
            assert!(Arc::ptr_eq(materialized, selected));
            assert!(Arc::ptr_eq(materialized.owner(), selected.owner()));
        }
    }

    #[test]
    fn generic_data_csv_typed_view_handles_table_shapes() {
        use crate::validation::json::{
            json_document_ast_from_source_bytes, JsonSourceValidationRequest,
        };

        let schema_registry = SchemaRegistry::with_builtin_schemas();
        let conversion_registry = ConversionRegistry::with_builtin_converters();
        let environment = ConversionOutputPipelineEnvironment {
            schema_registry: &schema_registry,
            conversion_registry: &conversion_registry,
            package_artifact_reader: None,
            artifact_cache: None,
        };
        for (name, source, expected) in [
            (
                "duplicate mapping names",
                r#"{"name":"Ada","name":"Later","active":true}"#,
                "name,active\nAda,true\n",
            ),
            (
                "ragged mapping rows and exact number",
                r#"[{"name":"Ada","score":1.2300e+4},{"name":"Lin"}]"#,
                "name,score\nAda,1.2300e+4\nLin,\n",
            ),
            ("row sequences", r#"[["a","b"],["c"]]"#, "a,b\nc\n"),
            ("scalar null", "null", "\n"),
            ("empty sequence", "[]", "\n"),
        ] {
            let (document, parse_diagnostics) =
                json_document_ast_from_source_bytes(JsonSourceValidationRequest {
                    bytes: source.as_bytes(),
                    source_uri: "builtin:generic-data-csv-shape",
                    content_type: Some(JSON_CONTENT_TYPE),
                });
            assert!(
                parse_diagnostics
                    .iter()
                    .all(|diagnostic| !diagnostic.severity.is_hard_violation()),
                "{name}: {parse_diagnostics:?}"
            );
            let ast = document.expect("lossless JSON AST").to_generic_data_ast();
            let (subject, diagnostics) = GenericDataCsvDocumentOutputSubject::new(ast);
            assert!(diagnostics.is_empty(), "{name}: {diagnostics:?}");
            let scope = ScopeConfig {
                cemt_formatter_profile: Some("compact".to_owned()),
                ..ScopeConfig::default()
            };
            let execution = execute_csv_document_output_pipeline_with_environment(
                &environment,
                subject,
                &scope,
                Some("builtin:generic-data-csv-shape"),
            );
            assert!(
                execution.diagnostics.is_empty(),
                "{name}: {:?}",
                execution.diagnostics
            );
            assert_eq!(
                execution.output.as_ref().and_then(Value::as_str),
                Some(expected),
                "{name}"
            );
            let materialized = execution
                .formatted_materialized_cemt_tree
                .as_ref()
                .unwrap_or_else(|| panic!("{name}: materialized generic-data CSV tree"));
            assert_eq!(
                materialized.input_provenance().representation_id,
                "cem.generic-data-document-ast+csv-view"
            );
            let stage_output = execution
                .materialized_cemt_stage_output
                .as_ref()
                .unwrap_or_else(|| panic!("{name}: typed generic-data CSV stage output"));
            let TransformArtifactBody::MaterializedCemtTree(selected) = &stage_output.body else {
                panic!("{name}: generic-data CSV stage output must be materialized")
            };
            assert!(Arc::ptr_eq(materialized, selected));
        }
    }

    #[test]
    fn generic_data_csv_typed_view_rejects_nested_values_before_formatter() {
        use crate::validation::csv::GENERIC_DATA_CSV_NESTED_VALUE_UNSUPPORTED_CODE;
        use crate::validation::json::{
            json_document_ast_from_source_bytes, JsonSourceValidationRequest,
        };

        let (document, parse_diagnostics) =
            json_document_ast_from_source_bytes(JsonSourceValidationRequest {
                bytes: br#"{"nested":{"value":1}}"#,
                source_uri: "builtin:nested-generic-data-csv",
                content_type: Some(JSON_CONTENT_TYPE),
            });
        assert!(parse_diagnostics.is_empty(), "{parse_diagnostics:?}");
        let ast = document.expect("lossless JSON AST").to_generic_data_ast();
        let (_subject, diagnostics) = GenericDataCsvDocumentOutputSubject::new(ast);
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(
            diagnostics[0].code,
            GENERIC_DATA_CSV_NESTED_VALUE_UNSUPPORTED_CODE
        );
        assert!(diagnostics[0].severity.is_hard_violation());
    }

    #[test]
    fn builtin_csv_typed_color_pipeline_retains_formatted_owner_and_selected_overlay() {
        use crate::validation::csv::{
            csv_document_ast_from_source_bytes, CsvSourceValidationRequest,
        };

        let schema_registry = SchemaRegistry::with_builtin_schemas();
        let conversion_registry = ConversionRegistry::with_builtin_converters();
        let environment = ConversionOutputPipelineEnvironment {
            schema_registry: &schema_registry,
            conversion_registry: &conversion_registry,
            package_artifact_reader: None,
            artifact_cache: None,
        };
        let (document, diagnostics) =
            csv_document_ast_from_source_bytes(CsvSourceValidationRequest {
                bytes: b"id,name\n1,Ada\n",
                source_uri: "builtin:typed-colored-csv-output",
                content_type: Some("text/csv; header=present"),
            });
        assert!(diagnostics.is_empty(), "{diagnostics:?}");
        let document = document.expect("typed CSV AST");

        for profile in ["terminal", "html", "md"] {
            let target_scope = ScopeConfig {
                cemt_formatter_profile: Some("compact".to_owned()),
                cemt_color_profile: Some(profile.to_owned()),
                ..ScopeConfig::default()
            };
            let execution = execute_csv_document_output_pipeline_with_environment(
                &environment,
                document.clone(),
                &target_scope,
                Some("builtin:typed-colored-csv-output"),
            );
            assert!(
                execution.diagnostics.is_empty(),
                "{profile}: {:?}",
                execution.diagnostics
            );
            let formatted = execution
                .formatted_materialized_cemt_tree
                .as_ref()
                .unwrap_or_else(|| panic!("{profile} formatted CSV tree"));
            let colored = execution
                .colored_materialized_cemt_tree
                .as_ref()
                .unwrap_or_else(|| panic!("{profile} colored CSV tree"));
            assert!(Arc::ptr_eq(formatted.owner(), colored.owner()));
            assert!(colored.color_overlay().is_some());
            let stage_output = execution
                .materialized_cemt_stage_output
                .as_ref()
                .unwrap_or_else(|| panic!("{profile} selected CSV stage output"));
            let TransformArtifactBody::MaterializedCemtTree(selected) = &stage_output.body else {
                panic!("{profile} CSV stage output must be materialized")
            };
            assert!(Arc::ptr_eq(colored, selected));
            if profile == "html" {
                assert!(execution
                    .output
                    .as_ref()
                    .and_then(Value::as_str)
                    .is_some_and(|output| output
                        .starts_with(&csv_html_preview_prefix(default_formatter_tab_size()))));
            } else {
                assert_eq!(
                    strip_ansi_codes(execution.output.as_ref().and_then(Value::as_str).unwrap()),
                    "id,name\n1,Ada\n"
                );
            }
        }
    }

    #[test]
    fn builtin_csv_output_pipeline_renders_html_color_backend_with_terminal_text_parity() {
        let schema_registry = SchemaRegistry::with_builtin_schemas();
        let conversion_registry = ConversionRegistry::with_builtin_converters();
        let environment = ConversionOutputPipelineEnvironment {
            schema_registry: &schema_registry,
            conversion_registry: &conversion_registry,
            package_artifact_reader: None,
            artifact_cache: None,
        };
        let table = csv_document(
            "id,name,active\n1,Ada,true\n2,Lin,false\n",
            Some(CSV_CONTENT_TYPE),
        );
        let terminal_scope = ScopeConfig {
            cemt_formatter_profile: Some("tabular".to_owned()),
            output_color_type: Some("ansi-256".to_owned()),
            ..ScopeConfig::default()
        };
        let html_scope = ScopeConfig {
            cemt_formatter_profile: Some("tabular".to_owned()),
            output_color_type: Some("html-css-vars".to_owned()),
            ..ScopeConfig::default()
        };
        let html_color_profile_scope = ScopeConfig {
            cemt_formatter_profile: Some("tabular".to_owned()),
            cemt_color_profile: Some("html".to_owned()),
            ..ScopeConfig::default()
        };
        let html_tab_size_scope = ScopeConfig {
            cemt_formatter_profile: Some("tabular".to_owned()),
            cemt_formatter_options: BTreeMap::from([("tabSize".to_owned(), "6".to_owned())]),
            output_color_type: Some("html-css-vars".to_owned()),
            ..ScopeConfig::default()
        };
        let plain_scope = ScopeConfig {
            cemt_formatter_profile: Some("tabular".to_owned()),
            cemt_color_profile: Some("terminal".to_owned()),
            output_color_type: Some("none".to_owned()),
            ..ScopeConfig::default()
        };

        let terminal = execute_csv_document_output_pipeline_with_environment(
            &environment,
            table.clone(),
            &terminal_scope,
            Some("builtin:csv-terminal-output"),
        );
        let html = execute_csv_document_output_pipeline_with_environment(
            &environment,
            table.clone(),
            &html_scope,
            Some("builtin:csv-html-output"),
        );
        let html_color_profile = execute_csv_document_output_pipeline_with_environment(
            &environment,
            table.clone(),
            &html_color_profile_scope,
            Some("builtin:csv-html-color-profile-output"),
        );
        let html_tab_size = execute_csv_document_output_pipeline_with_environment(
            &environment,
            table.clone(),
            &html_tab_size_scope,
            Some("builtin:csv-html-tab-size-output"),
        );
        let plain = execute_csv_document_output_pipeline_with_environment(
            &environment,
            table,
            &plain_scope,
            Some("builtin:csv-plain-output"),
        );

        assert!(
            terminal.diagnostics.is_empty(),
            "{:?}",
            terminal.diagnostics
        );
        assert!(html.diagnostics.is_empty(), "{:?}", html.diagnostics);
        assert!(
            html_color_profile.diagnostics.is_empty(),
            "{:?}",
            html_color_profile.diagnostics
        );
        assert!(
            html_tab_size.diagnostics.is_empty(),
            "{:?}",
            html_tab_size.diagnostics
        );
        assert!(plain.diagnostics.is_empty(), "{:?}", plain.diagnostics);
        assert!(terminal.format_elapsed_ns.is_some());
        assert!(terminal.color_elapsed_ns.is_some());
        assert!(terminal.writer_elapsed_ns.is_some());
        assert!(plain.format_elapsed_ns.is_some());
        assert!(plain.color_elapsed_ns.is_some());
        assert!(plain.writer_elapsed_ns.is_some());
        let terminal_text =
            strip_ansi_codes(terminal.output.as_ref().and_then(Value::as_str).unwrap());
        let html_output = html.output.as_ref().and_then(Value::as_str).unwrap();
        let html_color_profile_output = html_color_profile
            .output
            .as_ref()
            .and_then(Value::as_str)
            .unwrap();
        let plain_output = plain.output.as_ref().and_then(Value::as_str).unwrap();
        assert!(
            html_output.starts_with(&csv_html_preview_prefix(default_formatter_tab_size())),
            "{html_output}"
        );
        assert!(
            html_color_profile_output
                .starts_with(&csv_html_preview_prefix(default_formatter_tab_size())),
            "{html_color_profile_output}"
        );
        assert!(
            html_tab_size
                .output
                .as_ref()
                .and_then(Value::as_str)
                .is_some_and(|output| output.starts_with(&csv_html_preview_prefix(6))),
            "{:?}",
            html_tab_size.output
        );
        assert!(
            html_output.contains(r#"data-role="data.field.1""#),
            "{html_output}"
        );
        assert!(
            html_output.contains(r#"style="color: var(--cem-color-data-field-1, "#),
            "{html_output}"
        );
        assert!(html_output.ends_with("</pre>\n"), "{html_output}");
        assert!(
            html_color_profile_output.ends_with("</pre>\n"),
            "{html_color_profile_output}"
        );
        assert_eq!(
            html_text_content(html_output.strip_suffix('\n').unwrap_or(html_output)),
            terminal_text
        );
        assert_eq!(
            html_text_content(
                html_color_profile_output
                    .strip_suffix('\n')
                    .unwrap_or(html_color_profile_output)
            ),
            terminal_text
        );
        assert!(
            html_color_profile_output.contains(r#"style="color: var(--cem-color-data-field-1, "#),
            "{html_color_profile_output}"
        );
        assert!(!plain_output.contains('\u{1b}'), "{plain_output}");
        assert_eq!(plain_output, terminal_text);
    }

    #[test]
    fn builtin_csv_output_pipeline_generates_output_spans_from_formatter_tokens() {
        let schema_registry = SchemaRegistry::with_builtin_schemas();
        let conversion_registry = ConversionRegistry::with_builtin_converters();
        let environment = ConversionOutputPipelineEnvironment {
            schema_registry: &schema_registry,
            conversion_registry: &conversion_registry,
            package_artifact_reader: None,
            artifact_cache: None,
        };
        let table = csv_document("id,name\n", Some(CSV_CONTENT_TYPE));
        let target_scope = ScopeConfig {
            cemt_formatter_profile: Some("compact".to_owned()),
            ..ScopeConfig::default()
        };

        let execution = execute_csv_document_output_pipeline_with_environment(
            &environment,
            table,
            &target_scope,
            Some("builtin:csv-output-spans"),
        );

        assert!(
            execution.diagnostics.is_empty(),
            "{:?}",
            execution.diagnostics
        );
        assert_eq!(
            execution.output.as_ref().and_then(Value::as_str),
            Some("id,name\n")
        );
        assert_eq!(execution.output_spans.len(), 4);
        for (index, (output_start, output_len, source_start, source_len)) in [
            (0u64, 2u32, 0u64, 2u32),
            (2u64, 1u32, 2u64, 1u32),
            (3u64, 4u32, 3u64, 4u32),
            (7u64, 1u32, 7u64, 1u32),
        ]
        .into_iter()
        .enumerate()
        {
            let span = &execution.output_spans[index];
            assert_eq!(span.output_range.start, output_start, "span {index}");
            assert_eq!(span.output_range.len, output_len, "span {index}");
            let frame = span
                .origin
                .frames
                .first()
                .unwrap_or_else(|| panic!("span {index} has origin frame"));
            assert_eq!(frame.source_id, SourceId(1), "span {index}");
            match frame.span {
                crate::source_map::FrameSpan::Single(range) => {
                    assert_eq!(range.start, source_start, "span {index}");
                    assert_eq!(range.len, source_len, "span {index}");
                }
                crate::source_map::FrameSpan::Multi(_) => {
                    panic!("span {index} should have a single source range")
                }
            }
        }
    }

